package agentcoord

import (
 "crypto/sha256"
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "net/url"
 "os"
 "path/filepath"
 "regexp"
 "strings"
)

const GraphPath = ".entire/graph-agent.md"
const BrainPath = ".entire/brain-agent.md"
const Limit = 4 << 20

type Mode struct { Graph, Brain bool }
// StateDir and ConfigDir are Brain's existing plugin directories, not Graph's
// data/cache directory. Empty values use Brain's XDG defaults.
type Dirs struct { StateDir, ConfigDir string }

// Context uses only local filesystem metadata. Explicit and host paths are
// project roots (also allowed without Git). Implicit paths walk to the nearest
// .git entry; outside a repository the empty result means reference guidance.
func Context(explicit, host string) (string, error) {
 p := explicit
 if p == "" { p = host }
 if p != "" { return canonical(p) }
 p, err := os.Getwd(); if err != nil { return "", err }
 for {
  _, err := os.Lstat(filepath.Join(p,".git"))
  if err == nil { return canonical(p) }
  if !errors.Is(err,os.ErrNotExist) { return "",err }
  parent:=filepath.Dir(p); if parent==p { return "",nil }; p=parent
 }
}
func canonical(p string) (string,error) {
 p,err:=filepath.Abs(p); if err!=nil{return "",err}
 return filepath.EvalSymlinks(p)
}

// Read is a bounded, regular-file-only, root-confined read. Missing is the only
// absent state. A dangling link, unreadable file, FIFO, malformed record, or
// escaping link is an error, never a reason to silently select another mode.
func Read(root *os.Root, name string) ([]byte, bool, error) {
 info,err:=root.Lstat(name)
 if errors.Is(err,os.ErrNotExist) {return nil,false,nil}
 if err!=nil{return nil,false,err}
 if info.Mode() & os.ModeSymlink != 0 {return nil,false,fmt.Errorf("setup record %s must not be a symbolic link",name)}
 if !info.Mode().IsRegular() || info.Mode().Perm()&0444==0 {return nil,false,fmt.Errorf("setup record %s is not a readable regular file",name)}
 f,err:=root.Open(name);if err!=nil{return nil,false,err};defer f.Close()
 info,err=f.Stat();if err!=nil{return nil,false,err}
 if !info.Mode().IsRegular(){return nil,false,fmt.Errorf("setup record %s is not regular",name)}
 data,err:=io.ReadAll(io.LimitReader(f,Limit+1));if err!=nil{return nil,false,err}
 if len(data)>Limit{return nil,false,fmt.Errorf("setup record %s exceeds size limit",name)}
 return data,true,nil
}

// Resolve combines repository agent activation with Brain's actual setup
// record. The initializer's own activation is prospective; display uses the
// recorded mode, falling back to the requested standalone reference only when
// neither tool has been activated. No cache/index is consulted.
func Resolve(repo, product string, activate bool, dirs Dirs, remote string) (Mode,error) {
 m:=Mode{}
 if repo=="" {m.Graph=product=="graph";m.Brain=product=="brain";return m,nil}
 root,err:=os.OpenRoot(repo);if err!=nil{return m,err};defer root.Close()
 for _,p:=range []struct{name,product string;dst *bool}{{GraphPath,"graph",&m.Graph},{BrainPath,"brain",&m.Brain}} {
  // Own guide is an output, historically replaceable even when user-edited.
  // Existing aliases remain handled by the owning installer's write guards.
  if activate && p.product==product { *p.dst=true;continue }
  data,exists,err:=Read(root,p.name);if err!=nil{return m,err}
  if exists {
   heading:=strings.SplitN(string(data),"\n",2)[0]
   if heading!="# entire-graph — instructions for coding agents (follow directly)" && heading!="# Entire Brain coding-agent guide" && heading!="# Entire Graph and Brain coding-agent guide" {return m,fmt.Errorf("malformed agent activation %s: unrecognized guide heading",p.name)}
   *p.dst=true
  }
 }
 configured,err:=brainSetup(repo,remote,dirs);if err!=nil{return m,err};m.Brain=m.Brain||configured
 if !m.Graph&&!m.Brain {m.Graph=product=="graph";m.Brain=product=="brain"}
 return m,nil
}

func stateRoot(override, xdg, fallback string)(string,error){
 if override!="" {if !filepath.IsAbs(override){return "",fmt.Errorf("Brain state/config directory must be absolute")};return override,nil}
 if p:=os.Getenv(xdg);filepath.IsAbs(p){return filepath.Join(p,"entire"),nil}
 home,err:=os.UserHomeDir();if err!=nil{return "",err};return filepath.Join(home,fallback,"entire"),nil
}
func readPath(path string)([]byte,bool,error){
 // Open the filesystem root so absent ancestors stay distinguishable from
 // inaccessible ancestors. The target is fixed by a validated repository key.
 volume:=filepath.VolumeName(path)+string(filepath.Separator)
 root,err:=os.OpenRoot(volume);if err!=nil{return nil,false,err};defer root.Close()
 rel,err:=filepath.Rel(volume,path);if err!=nil{return nil,false,err}
 return Read(root,rel)
}
func brainSetup(repo, remote string, dirs Dirs)(bool,error){
 state,err:=stateRoot(dirs.StateDir,"XDG_STATE_HOME",filepath.Join(".local","state"));if err!=nil{return false,err}
 cfg,err:=stateRoot(dirs.ConfigDir,"XDG_CONFIG_HOME",".config");if err!=nil{return false,err}
 key,err:=repoKey(repo,remote,cfg);if err!=nil{return false,err}
 if key==""{return false,nil} // unknown host without a learned mapping: never configured
 path:=filepath.Join(state,"repos",filepath.FromSlash(key),"setup.json")
 data,exists,err:=readPath(path);if err!=nil{return false,fmt.Errorf("read Brain setup: %w",err)}
 if !exists{return false,nil}
 var record struct {SchemaVersion int `json:"schema_version"`}
 if err:=json.Unmarshal(data,&record);err!=nil{return false,fmt.Errorf("malformed Brain setup %s: %w",path,err)}
 if record.SchemaVersion!=1{return false,fmt.Errorf("unsupported Brain setup schema in %s",path)}
 return true,nil
}
var unsafeComponent=regexp.MustCompile(`[^a-zA-Z0-9._-]+`)
var scpRemote=regexp.MustCompile(`^(?:[^@]+@)?([^:/]+):(.+)$`)
func component(s string)string{return strings.Trim(unsafeComponent.ReplaceAllString(s,"-"),"-._")}
func repoKey(repo,remote,cfg string)(string,error){
 remote=strings.TrimSpace(remote)
 var host,path string
 if u,err:=url.Parse(remote);err==nil && strings.Contains(remote,"://") && u.Host!="" {
  host=strings.ToLower(u.Hostname());path=u.Path
  if strings.EqualFold(u.Scheme,"entire"){host="entire"}
 } else if m:=scpRemote.FindStringSubmatch(remote);len(m)==3 && !(len(m[1])==1 && (strings.HasPrefix(m[2],"/")||strings.Contains(m[2],"\\")||!strings.Contains(m[2],"/"))) {
  host=strings.ToLower(m[1]);path=m[2]
 } else if h,p,ok:=strings.Cut(remote,"/");ok&&strings.Contains(h,"."){host=strings.ToLower(h);path=p}
 if host=="" {
  sum:=sha256.Sum256([]byte(repo));base:=component(filepath.Base(repo));if base==""{base="repo"}
  return fmt.Sprintf("local/%s-%x",base,sum[:6]),nil
 }
 var parts []string
 for _,p:=range strings.Split(strings.TrimSuffix(strings.Trim(strings.TrimSpace(path),"/"),".git"),"/") {if p=component(strings.ToLower(p));p!=""{parts=append(parts,p)}}
 if len(parts)==0{return "",nil}
 if host=="entire" {if len(parts)<3||parts[0]=="workspaces"{return "",fmt.Errorf("invalid Entire repository identity")};return strings.Join(parts,"/"),nil}
 slug:=map[string]string{"github.com":"gh","gitlab.com":"gl","bitbucket.org":"bb","entire.io":"et","tangled.org":"tg","code.storage":"cs"}[host]
 if slug=="" {
  data,exists,err:=readPath(filepath.Join(cfg,"brain.json"));if err!=nil{return "",err};if !exists{return "",nil}
  var config struct { DomainSlugs map[string]string `json:"domain_slugs"` }
  if err:=json.Unmarshal(data,&config);err!=nil{return "",fmt.Errorf("malformed Brain config: %w",err)}
  slug=config.DomainSlugs[host];if slug==""{return "",nil}
 }
 if component(slug)!=slug||slug=="workspaces"{return "",fmt.Errorf("invalid Brain host mapping")}
 return strings.Join(append([]string{slug},parts...),"/"),nil
}
EOF
