package agentcoord

import (
 "errors"
 "fmt"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
)

// Remote reads the local origin configuration only. Git config executes no
// hooks or transports, and --no-includes avoids following repository includes.
func Remote(repo string)(string,error){
 if repo=="" {return "",nil}
 if _,err:=os.Lstat(filepath.Join(repo,".git"));errors.Is(err,os.ErrNotExist){return "",nil}else if err!=nil{return "",err}
 cmd:=exec.Command("git","-C",repo,"config","--local","--no-includes","--get","remote.origin.url")
 for _,e:=range os.Environ(){k,_,_:=strings.Cut(e,"=");if !strings.HasPrefix(k,"GIT_"){cmd.Env=append(cmd.Env,e)}}
 cmd.Env=append(cmd.Env,"GIT_CONFIG_NOSYSTEM=1","GIT_CONFIG_GLOBAL="+os.DevNull)
 data,err:=cmd.Output()
 var status *exec.ExitError
 if errors.As(err,&status)&&status.ExitCode()==1{return "",nil}
 if err!=nil{return "",fmt.Errorf("read local repository identity: %w",err)}
 return strings.TrimSpace(string(data)),nil
}
EOF
