  if os.IsNotExist(err){continue};if err!=nil{return nil,err}
  if !info.Mode().IsRegular(){return nil,fmt.Errorf("%s is not a regular guide",name)}
  if err:=ensureNoSharedInode(root,name);err!=nil{return nil,err}
  for _,other:=range []string{"AGENTS.md","CLAUDE.md"}{
   target,err:=statContainedFile(root,other);if err==nil&&os.SameFile(info,target){return nil,fmt.Errorf("legacy guide %s aliases instruction file %s",name,other)}
  }
