  target,err:=statContainedFile(root,Path);if err==nil&&os.SameFile(info,target){continue}
  resolved,err:=resolveContainedName(root,name);if err!=nil{return nil,err}
  canonical,err:=resolveContainedName(root,Path);if err!=nil{return nil,err}
  if sameResolvedName(resolved,canonical){continue}
