// Context gives explicit roots precedence over the host root; otherwise it finds
// the nearest Git root without invoking Git. Explicit roots can be non-Git projects.
func Context(explicit,host string)(string,error){
 p:=explicit;if p==""{p=host}
 if p!=""{return filepath.Abs(p)}
 p,err:=os.Getwd();if err!=nil{return "",err}
 for {
  _,err:=os.Lstat(filepath.Join(p,".git"));if err==nil{return p,nil};if !os.IsNotExist(err){return "",err}
  parent:=filepath.Dir(p);if parent==p{return "",nil};p=parent
 }
}

// safeKey permits only Brain's normalized repository-key components.
func safeKey(key string)bool{
 if key==""||strings.Contains(key,"\\"){return false}
 parts:=strings.Split(key,"/");if parts[0]=="workspaces"{return false}
 for _,p:=range parts{if p==""||p=="."||p==".."||cleanComponent(p)!=p{return false}}
