 installed,err:=parsePluginList(raw);if err!=nil{return "",err}
 if product=="brain"{if installed["graph"]{return CombinedGuide,nil};return BrainGuide(),nil}
 if installed["brain"] {
  exists,err:=repositoryBrain(repo,opts);if err!=nil{return "",err}
  if exists{return CombinedGuide,nil}
