type limitedBuffer struct {bytes.Buffer; limit int}
func(b *limitedBuffer)Write(p []byte)(int,error){if b.Len()+len(p)>b.limit{return 0,fmt.Errorf("command output exceeds limit")};return b.Buffer.Write(p)}
func localCommand(repo,name string,args ...string)(string,error){
 ctx,cancel:=context.WithTimeout(context.Background(),15*time.Second);defer cancel()
 cmd:=exec.CommandContext(ctx,name,args...);cmd.Dir=repo
 cmd.Env=os.Environ()
 if name=="git"{
  cmd.Env=nil
