var pluginName=regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9_-]*$`)
func parsePluginList(raw string)(map[string]bool,error){
 installed:=map[string]bool{}
 lines:=strings.Split(strings.TrimSpace(raw),"\n")
 if len(lines)==2&&strings.HasPrefix(lines[0],"No plugins installed in ")&&strings.HasPrefix(lines[1],"Install one with 'entire plugin install "){return installed,nil}
 if len(lines)==0||!strings.HasPrefix(lines[0],"Managed plugin directory: "){return nil,fmt.Errorf("unrecognized entire plugin list output")}
 for _,line:=range lines[1:]{
