  if installed[fields[0]]{return nil,fmt.Errorf("duplicate plugin list entry %s",fields[0])}
  installed[fields[0]]=true
 }
 if len(installed)==0{return nil,fmt.Errorf("empty managed plugin listing")}
 return installed,nil
}
