 if dir!=""{if !filepath.IsAbs(dir){return "",fmt.Errorf("%s must be absolute",override)};return dir,nil}
 if dir=os.Getenv(xdg);filepath.IsAbs(dir){return filepath.Join(dir,"entire"),nil}
