 for _,part:=range strings.Split(filepath.ToSlash(name),"/"){
  prefix=filepath.Join(prefix,part);info,err=root.Lstat(prefix)
  if os.IsNotExist(err){return nil,false,nil};if err!=nil{return nil,false,err}
